import React from "react";
import {
  Provider,
  Input as SJInput,
  ResultsContainer,
  Paginator,
  Summary,
  Tabs,
  Filter,
  EVENT_SELECTION_UPDATED
} from "@sajari/sdk-react";

import ResultRenderer from "./result";
import config from "./sajari";

function Container(props) {
  return (
    <Provider
      {...config}
      searchOnLoad
      theme={{ colors: { brand: { primary: "#002c58" } } }}
    >
      {props.children}
    </Provider>
  );
}

export function Input() {
  return (
    <Container>
      <SJInput mode="typeahead" dropdownMode="suggestions" />
    </Container>
  );
}

// Documentation on filter strings https://github.com/sajari/website-search-integration#using-operators
const tabsFilter = new Filter(
  {
    All: "",
    Categories: "category='Categories'",
    Products: "category='Products'",
    Articles: "category='Articles'",
    PDFs: "url$'.pdf'" // url ends with '.pdf'
  },
  "All"
);

// Add the filter to `values`.  Note: tabsFilter.filter() will be
// evaluated in `values.get()`.
config.search.values.set({ filter: () => tabsFilter.filter() });

// Trigger a search every time the filter selection changes.
tabsFilter.listen(EVENT_SELECTION_UPDATED, () =>
  config.search.pipeline.search(config.search.values.get())
);

export function Results() {
  return (
    <Container>
      <Summary />
      <Tabs
        filter={tabsFilter}
        tabs={[
          { name: "All", display: "All" },
          { name: "Categories", display: "Categories" },
          { name: "Products", display: "Products" },
          { name: "Articles", display: "Articles" },
          { name: "PDFs", display: "PDFs" }
        ]}
        styles={{
          container: {
            marginBottom: "1.5rem"
          }
        }}
      />
      <ResultsContainer>
        {({ error, results }) => {
          if (error) {
            console.error(error);
            return null;
          }

          return (
            <ol className="gg-results">
              {results.map(({ key, ...rest }) => {
                return (
                  <li key={key} className="gg-results__item">
                    <ResultRenderer {...rest} />
                  </li>
                );
              })}
            </ol>
          );
        }}
      </ResultsContainer>
      <Paginator
        styles={{
          container: {
            marginBottom: "2rem"
          },
          number: () => ({
            lineHeight: 1.7
          })
        }}
      />
    </Container>
  );
}
