import React from "react";
import { Popup } from "../lib/popup";
import { TokenLink } from "@sajari/sdk-react";
import { PDFIcon, PlayVideoIcon } from "./icons";

export default function ResultRenderer(props) {
  const { values, token, resultClicked } = props;

  return (
    <div className="gg-result">
      {values["image"] ? (
        <div className="gg-result__image">
          <TokenLink
            url={values["url"]}
            token={token}
            resultClicked={resultClicked}
          >
            <img src={values["image"]} />
          </TokenLink>
        </div>
      ) : // If the url ends with '.pdf' display the PDF Icon
      values["url"].endsWith(".pdf") ? (
        <div className="gg-result__image">
          <TokenLink
            url={values["url"]}
            token={token}
            resultClicked={resultClicked}
          >
            <PDFIcon />
          </TokenLink>
        </div>
      ) : null}

      <div className="gg-result__copy">
        <TokenLink
          url={values["url"]}
          token={token}
          resultClicked={resultClicked}
        >
          <h3 className="gg-result__title">{values["title"]}</h3>
        </TokenLink>

        {/* 
          Attempting to use onclick="ytpopup(id) where id = {values["ContainsVideo"]} 
          ytpopup function is defined in index.html
          */}
        {values["ContainsVideo"] && (
          <div className="gg-video">
            <div className="gg-pv">Play Video</div>
            <VideoPopup video={values["ContainsVideo"]} />
          </div>
        )}

        <div>
          {values["productmodel"] && (
            <span className="gg-sku" title={values["productmodel"]}>
              {values["productmodel"].indexOf(",") > 0 ? (
                <strong>Models: </strong>
              ) : (
                <strong>Model: </strong>
              )}
              {values["productmodel"]}
            </span>
          )}
          {values["productprice"] && (
            <span className="gg-price">
              <strong>Price: </strong>
              <span className="gg-price-value">{values["productprice"]}</span>
            </span>
          )}
        </div>
        <div className="gg-result__desc">{values["description"]}</div>
        <TokenLink
          className="gg-result__url"
          url={values["url"]}
          token={token}
          resultClicked={resultClicked}
        />
      </div>
    </div>
  );
}

function VideoPopup({ video }) {
  return (
    <Popup
      className={"gg-video-popup--" + video}
      href={video.startsWith("PLY") ? `https://www.youtube.com/embed/videoseries?list=${video}&rel=0` : `http://www.youtube.com/watch?v=${video}`}
      target="_blank"
      savefrom_lm_index="0"
      savefrom_lm="1"
      config={popupConfig}
    >
      <PlayVideoIcon />
    </Popup>
  );
}

const popupConfig = {
  disableOn: 700,
  type: "iframe",
  mainClass: "mfp-fade",
  removalDelay: 160,
  preloader: false,
  fixedContentPos: false,
  iframe: {
    patterns: {
      youtube: {
        index: 'youtube.com/',
        id: 'v=', 
        src: '//www.youtube.com/embed/%id%?rel=0' 
      }
    }
  },
  srcAction: 'iframe_src'
};
